'use strict';

var Linter = require( 'eslint' ).Linter;
var rule = require( './../lib' );

var linter = new Linter();
var code = [
	'/**',
	'* Squares a number.',
	'*',
	'* @example',
	'* var y = square( 3.0 )',
	'* // returns 9.0',
	'*/',
	'function square( x ) {',
	'\treturn x * x;',
	'}'
].join( '\n' );

linter.defineRule( 'jsdoc-example-eslint', rule );

var result = linter.verify( code, {
	'rules': {
		'jsdoc-example-eslint': [ 'error', {
			'rules': {
				'semi': 'error'
			}
		}]
	}
});
console.log( result );
